package com.cdg.ordersupport.auth;
import com.cdg.ordersupport.auth.dto.*; import com.cdg.ordersupport.common.ApiException; import com.cdg.ordersupport.security.JwtTokenService; import com.cdg.ordersupport.user.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder passwords; private final JwtTokenService tokens; public AuthService(UserRepository u,PasswordEncoder p,JwtTokenService t){users=u;passwords=p;tokens=t;} public AuthResponse register(RegisterRequest r){if(users.findByEmail(r.email()).isPresent())throw new ApiException(HttpStatus.CONFLICT,"CONFLICT","Email already registered");return response(users.save(new User(r.email(),passwords.encode(r.password()),r.displayName(),Role.CUSTOMER)));} public AuthResponse login(LoginRequest r){User u=users.findByEmail(r.email()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"UNAUTHORIZED","Invalid credentials"));if(!passwords.matches(r.password(),u.getPasswordHash()))throw new ApiException(HttpStatus.UNAUTHORIZED,"UNAUTHORIZED","Invalid credentials");return response(u);} public AuthResponse me(String id){User u=users.findById(java.util.UUID.fromString(id)).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"UNAUTHORIZED","User not found"));return response(u);} private AuthResponse response(User u){return new AuthResponse(tokens.create(u),u.getRole(),u.getDisplayName());} }
